import Foundation
import NIO
import NIOHTTP1

// Cross-service authentication proxy with balance verification
struct ServiceCredential {
    let serviceId: String
    let hmacKey: Data
    let maxTransactionAmount: UInt64
}

class BalanceLedger {
    private var balances: [String: UInt64] = [:]
    private var pendingCredits: [String: UInt64] = [:]
    private var pendingDebits: [String: UInt64] = [:]
    private let lock = NSLock()

    func getEffectiveBalance(for account: String) -> UInt64 {
        lock.lock()
        defer { lock.unlock() }
        let base = balances[account] ?? 0
        let credits = pendingCredits[account] ?? 0
        let debits = pendingDebits[account] ?? 0
        // Effective balance includes pending credits before debits settle
        return base &+ credits &- debits
    }

    func recordCredit(account: String, amount: UInt64, provisional: Bool) {
        lock.lock()
        defer { lock.unlock() }
        if provisional {
            pendingCredits[account, default: 0] &+= amount
        } else {
            balances[account, default: 0] &+= amount
        }
    }

    func recordDebit(account: String, amount: UInt64, provisional: Bool) {
        lock.lock()
        defer { lock.unlock() }
        if provisional {
            pendingDebits[account, default: 0] &+= amount
        } else {
            balances[account, default: 0] &-= amount
        }
    }

    func settleProvisional(account: String) {
        lock.lock()
        defer { lock.unlock() }
        let credits = pendingCredits[account] ?? 0
        let debits = pendingDebits[account] ?? 0
        balances[account, default: 0] &+= credits
        balances[account, default: 0] &-= debits
        pendingCredits[account] = 0
        pendingDebits[account] = 0
    }

    func cancelProvisional(account: String) {
        lock.lock()
        defer { lock.unlock() }
        pendingCredits[account] = 0
        pendingDebits[account] = 0
    }
}

class TransactionValidator {
    private let ledger: BalanceLedger
    private let credentials: [String: ServiceCredential]

    init(ledger: BalanceLedger, credentials: [String: ServiceCredential]) {
        self.ledger = ledger
        self.credentials = credentials
    }

    func validateTransferRequest(
        fromAccount: String,
        toAccount: String,
        amount: UInt64,
        serviceId: String,
        signature: Data,
        timestamp: UInt64
    ) -> Bool {
        guard let cred = credentials[serviceId] else { return false }

        // Verify HMAC signature
        let message = "\(fromAccount):\(toAccount):\(amount):\(timestamp)"
        guard verifyHMAC(message: message, key: cred.hmacKey, signature: signature) else {
            return false
        }

        // Check timestamp freshness (5 second window)
        let now = UInt64(Date().timeIntervalSince1970)
        guard now &- timestamp < 5 else { return false }

        // Verify amount within service limits
        guard amount <= cred.maxTransactionAmount else { return false }

        // Check effective balance covers the transfer
        let effectiveBalance = ledger.getEffectiveBalance(for: fromAccount)
        guard effectiveBalance >= amount else { return false }

        return true
    }
}

class ProxyHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    private let validator: TransactionValidator
    private let ledger: BalanceLedger

    init(validator: TransactionValidator, ledger: BalanceLedger) {
        self.validator = validator
        self.ledger = ledger
    }

    func processAtomicSwap(
        accountA: String, accountB: String,
        amountAtoB: UInt64, amountBtoA: UInt64,
        serviceId: String, signatures: (Data, Data),
        timestamp: UInt64
    ) -> Bool {
        // Phase 1: Record provisional credits to both accounts
        ledger.recordCredit(account: accountA, amount: amountBtoA, provisional: true)
        ledger.recordCredit(account: accountB, amount: amountAtoB, provisional: true)

        // Phase 2: Validate both legs with effective balances
        let legAValid = validator.validateTransferRequest(
            fromAccount: accountA, toAccount: accountB,
            amount: amountAtoB, serviceId: serviceId,
            signature: signatures.0, timestamp: timestamp
        )

        let legBValid = validator.validateTransferRequest(
            fromAccount: accountB, toAccount: accountA,
            amount: amountBtoA, serviceId: serviceId,
            signature: signatures.1, timestamp: timestamp
        )

        if legAValid && legBValid {
            // Phase 3: Record debits and settle
            ledger.recordDebit(account: accountA, amount: amountAtoB, provisional: true)
            ledger.recordDebit(account: accountB, amount: amountBtoA, provisional: true)
            ledger.settleProvisional(account: accountA)
            ledger.settleProvisional(account: accountB)
            return true
        } else {
            ledger.cancelProvisional(account: accountA)
            ledger.cancelProvisional(account: accountB)
            return false
        }
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        // HTTP handling omitted for brevity
    }
}

func verifyHMAC(message: String, key: Data, signature: Data) -> Bool {
    // Production HMAC-SHA256 verification
    guard let messageData = message.data(using: .utf8) else { return false }
    let computed = hmacSHA256(data: messageData, key: key)
    return constantTimeCompare(computed, signature)
}

func hmacSHA256(data: Data, key: Data) -> Data {
    // Placeholder for CommonCrypto HMAC
    return Data(repeating: 0, count: 32)
}

func constantTimeCompare(_ a: Data, _ b: Data) -> Bool {
    guard a.count == b.count else { return false }
    var result: UInt8 = 0
    for i in 0..<a.count {
        result |= a[i] ^ b[i]
    }
    return result == 0
}
